#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Patch integrer_carte.py : mode autonome ?carte = titre + icône pour le
raccourci « Éditer les cartes » sur l'écran d'accueil de la tablette."""
import sys

CHEMIN = 'build/integrer_carte.py'
src = open(CHEMIN, encoding='utf-8').read()
icone = open('carte/img/icone-raccourci.b64').read().strip()

def remplacer(s, vieux, neuf, nom):
    if s.count(vieux) != 1:
        print('ECHEC %s' % nom)
        print(repr(vieux[:160]))
        sys.exit(1)
    return s.replace(vieux, neuf, 1)

# ---- 1. constante icône dans l'addon (avant la fonction decodB64) ----
src = remplacer(src,
"""  var BUNDLE_B64 = '__BUNDLE_B64__';""",
"""  var BUNDLE_B64 = '__BUNDLE_B64__';

  /* Icône du raccourci « Éditer les cartes » (logo, 96 px, data URI) :
     utilisée comme favicon de la page quand le module est ouvert en
     mode autonome (?carte) — c'est elle que Chrome place sur l'écran
     d'accueil de la tablette lors de « Ajouter à l'écran d'accueil ». */
  var ICONE_RACCOURCI = 'data:image/png;base64,';""", 'constante icône')

# ---- 2. demarrer : en mode autonome, titre + favicon avant l'ouverture ----
src = remplacer(src,
"""    if (enModeCarte()) { ouvrirModule(); return; }""",
"""    if (enModeCarte()) {
      // Mode autonome (raccourci « Éditer les cartes » de la tablette) :
      // titre et icône propres, pour le raccourci d'écran d'accueil.
      document.title = 'Éditer les cartes — La Trattoria';
      var lk = document.createElement('link');
      lk.rel = 'icon';
      lk.type = 'image/png';
      lk.href = ICONE_RACCOURCI;
      document.head.appendChild(lk);
      var at = document.createElement('link');
      at.rel = 'apple-touch-icon';
      at.href = ICONE_RACCOURCI;
      document.head.appendChild(at);
      var mt = document.querySelector('meta[name="theme-color"]');
      if (!mt) {
        mt = document.createElement('meta');
        mt.name = 'theme-color';
        document.head.appendChild(mt);
      }
      mt.content = '#24312B';
      ouvrirModule();
      return;
    }""", 'demarrer autonome')

open(CHEMIN, 'w', encoding='utf-8').write(src)
print('Patch raccourci appliqué')
